original:
async function saveAll(settings) {
  const saved = [];
  for (const setting of settings) {
    const res = await fetch('/api/settings/' + setting.key, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ value: setting.value }),
    });
    if (!res.ok) throw new Error('Could not save ' + setting.key + ': ' + res.status);
    saved.push(setting.key);
  }
  return saved;
}

