test('resolves with every saved key, in order', async () => {
  const saved = await saveAll([
    { key: 'theme', value: 'dark' },
    { key: 'language', value: 'en' },
  ]);
  assert.deepEqual(saved, ['theme', 'language']);
});

test('sends each setting as a JSON PUT', async () => {
  await saveAll([{ key: 'theme', value: 'dark' }]);
  const request = api.requests[0];
  assert.equal(request.method, 'PUT');
  assert.equal(request.url, '/api/settings/theme');
  assert.deepEqual(JSON.parse(request.body), { value: 'dark' });
});
